#include "MC33978AES.h"
#include "../../config.mcc/mcc_generated_files/system/pins.h"
#include "../registers.h"
#include "SpiHelper.h"
#include "string.h"

typedef struct {
  uint16_t switch_state;
  bool valid;
} MC33978AES_SwitchStatusResult;

static inline void MC33978AES_Select(void) { IO_CS_MC33978AES_SetLow(); }

static inline void MC33978AES_Deselect(void) { IO_CS_MC33978AES_SetHigh(); }

static bool MC33978AES_Exchange(uint8_t *buf_data, size_t buffer_size) {
  MC33978AES_Select();
  bool success = Spi0Helper_BufferExchange(buf_data, buffer_size);
  MC33978AES_Deselect();
  return success;
}

void MC33978AES_ConfigurePorts(void) {
  uint8_t buf_data[4] = {0b00000011, 0b00000000, 0b00001000, 0b10010001};
  MC33978AES_Exchange(buf_data, sizeof(buf_data));
}

void MC33978AES_DisableSpTriState(void) {
  uint8_t buf_data[4] = {0b00000101, 0b00000000, 0b00000000, 0x00};
  MC33978AES_Exchange(buf_data, sizeof(buf_data));
}

void MC33978AES_DisableSgTriState(void) {
  uint8_t buf_data[4] = {0b00000111, 0b00000000, 0x3F, 0xFC};
  MC33978AES_Exchange(buf_data, sizeof(buf_data));
}

void MC33978AES_LowPowerMode(void) {
  uint8_t buf_data[4] = {0b00111001, 0x00, 0x00, 0x00};
  MC33978AES_Exchange(buf_data, sizeof(buf_data));
}

static bool MC33978AES_RequestSwitchStatus(uint8_t exchange_buffer[4]) {
  exchange_buffer[0] = MC_CMD_READ_SWITCH_STATUS;
  exchange_buffer[1] = 0x00;
  exchange_buffer[2] = 0x00;
  exchange_buffer[3] = 0x00;
  return MC33978AES_Exchange(exchange_buffer, 4U);
}

static bool MC33978AES_IsSwitchStatusResponseValid(const uint8_t response[4]) {
  return response[0] == MC_CMD_READ_SWITCH_STATUS;
}

static uint16_t MC33978AES_DecodeSwitchStatus(const uint8_t response[4]) {
  uint16_t switch_state = 0x0000;

  switch_state |= (uint16_t)(response[3] & 0b00000001U) << 0; // SG0 -> bit 0 - BIT 0  : INPUT SEAT
  switch_state |= (uint16_t)(response[3] & 0b00000010U) << 0; // SG1 -> bit 1 - BIT 1  : INPUT BRAKE
  switch_state |= (uint16_t)(response[2] & 0b01000000U) >> 4; // SP0 -> bit 2 - BIT 14 : 12V NEIMAN SWITCH
  switch_state |= (uint16_t)(response[2] & 0b10000000U) >> 4; // SP1 -> bit 3 - BIT 15 : INPUT BACKWARD
  switch_state |= (uint16_t)(response[1] & 0b00000001U) << 4; // SP2 -> bit 4 - BIT 16 : OUT_AUX
  switch_state |= (uint16_t)(response[1] & 0b00000010U) << 4; // SP3 -> bit 5 - BIT 17 : INPUT FORWARD
  switch_state |= (uint16_t)(response[1] & 0b00000100U) << 4; // SP4 -> bit 6 - BIT 18 : PTO RUN
  switch_state |= (uint16_t)(response[1] & 0b00001000U) << 4; // SP5 -> bit 7 - BIT 19 : BT_AR
  switch_state |= (uint16_t)(response[1] & 0b00010000U) << 4; // SP6 -> bit 8 - BIT 20 : INPUT PTO
  switch_state |= (uint16_t)(response[1] & 0b00100000U) << 4; // SP7 -> bit 9 - BIT 21 : INPUT START ENGINE
  return switch_state;
}

static void MC33978AES_UpdateInputRegisters(uint16_t switch_state) {
  global_shadow_ram[REG_IN_B1] = switch_state & 0xFF;
  global_shadow_ram[REG_IN_B2] = (switch_state >> 8) & 0xFF;
}

static MC33978AES_SwitchStatusResult MC33978AES_ReadSwitchStatus(void) {
  uint8_t exchange_buffer[4];
  MC33978AES_SwitchStatusResult result = {0};

  for (uint8_t attempt = 0; attempt < MC33978AES_READ_ATTEMPTS; attempt++) {
    if (MC33978AES_RequestSwitchStatus(exchange_buffer) &&
        MC33978AES_IsSwitchStatusResponseValid(exchange_buffer)) {
      result.switch_state = MC33978AES_DecodeSwitchStatus(exchange_buffer);
      result.valid = true;
      return result;
    }
  }

  return result;
}

void MC33978AES_ReadState(void) {
  MC33978AES_SwitchStatusResult result = MC33978AES_ReadSwitchStatus();

  if (result.valid) {
    MC33978AES_UpdateInputRegisters(result.switch_state);
    _SWITCH_STATUS_DONE = true;
  }
}

void MC33978AES_Init(void) {
  MC33978AES_ConfigurePorts();
  MC33978AES_DisableSgTriState();
  MC33978AES_DisableSpTriState();
}

void MC33978AES_Loop(void) {
  _SWITCH_STATUS_DONE = false;
  MC33978AES_ReadState();
}